// One-shot harvest of Memelord's PUBLIC template library before the subscription ends.
// The assets are third-party cultural meme artifacts on a public bucket (no auth). We copy
// the MEDIA + factual metadata (names, dimensions, normalized box geometry) locally so the
// library survives account closure. Descriptions/tags are regenerated by OUR pipeline later.
// Resumable: re-run any time; it skips files already on disk.
//   node engine/harvest-memelord.js            (full run)
//   node engine/harvest-memelord.js --meta-only (just refresh the manifest)
const fs = require('fs');
const path = require('path');

const API = 'https://www.memelord.com/api/assets-public';
const BUCKET = 'https://phghyihcgkvblankxtie.supabase.co/storage/v1/object/public/public-assets';
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)';
const OUT = path.join(__dirname, '..', 'templates', 'harvest');
const MEDIA = path.join(OUT, 'media');
const PREV = path.join(OUT, 'previews');
const MANIFEST = path.join(OUT, 'manifest.json');
const CONCURRENCY = 6;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function fetchJSON(url, tries = 5) {
  for (let i = 0; i < tries; i++) {
    try {
      const r = await fetch(url, { headers: { 'User-Agent': UA } });
      if (r.status === 429 || r.status >= 500) { await sleep(1500 * (i + 1)); continue; }
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return await r.json();
    } catch (e) { if (i === tries - 1) throw e; await sleep(1000 * (i + 1)); }
  }
}

async function downloadTo(url, dest, tries = 4) {
  if (fs.existsSync(dest) && fs.statSync(dest).size > 0) return 'skip';
  for (let i = 0; i < tries; i++) {
    try {
      const r = await fetch(url, { headers: { 'User-Agent': UA } });
      if (r.status === 429 || r.status >= 500) { await sleep(1200 * (i + 1)); continue; }
      if (r.status === 404) return '404';
      if (!r.ok) throw new Error('HTTP ' + r.status);
      const buf = Buffer.from(await r.arrayBuffer());
      if (!buf.length) throw new Error('empty');
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.writeFileSync(dest, buf);
      return 'ok';
    } catch (e) { if (i === tries - 1) return 'err:' + e.message; await sleep(1000 * (i + 1)); }
  }
}

// keep only fields we actually use — drop their embeddings/search vectors (huge, useless to us)
function slimAsset(a) {
  return {
    id: a.id, name: a.name, canonical_name: a.canonical_name || null,
    type: a.type, width: a.width, height: a.height,
    storage_path: a.storage_path, preview_storage_path: a.preview_storage_path,
    removed_bg_storage_path: a.removed_bg_storage_path || null,
    tags: a.tags || [], extra_tags: a.extra_tags || [],
    description: a.description || '', visual_description: a.visual_description || '',
    text_position_data: a.text_position_data || null,
    composer_template: a.composer_template || null,
    caption_config: a.caption_config || null, force_top_caption: !!a.force_top_caption,
    face_swappable: !!a.face_swappable, copyright_free: a.copyright_free,
    category_id: a.category_id || null, aliases: a.aliases || null,
    created_at: a.created_at || null,
  };
}

async function pool(items, worker, size) {
  let idx = 0, done = 0;
  const results = { ok: 0, skip: 0, err: 0, m404: 0 };
  async function run() {
    while (idx < items.length) {
      const i = idx++;
      const r = await worker(items[i]);
      for (const k of r) { if (k === 'ok') results.ok++; else if (k === 'skip') results.skip++; else if (k === '404') results.m404++; else if (k) results.err++; }
      if (++done % 100 === 0) console.log(`  media ${done}/${items.length} (ok:${results.ok} skip:${results.skip} 404:${results.m404} err:${results.err})`);
    }
  }
  await Promise.all(Array.from({ length: size }, run));
  return results;
}

async function main() {
  fs.mkdirSync(MEDIA, { recursive: true });
  fs.mkdirSync(PREV, { recursive: true });

  // 1. paginate the whole library, dedupe by id
  console.log('fetching manifest…');
  const byId = new Map();
  const first = await fetchJSON(`${API}?page=1&per_page=100&sort=asc`);
  const totalPages = first.total_pages;
  console.log(`total ${first.total} assets across ${totalPages} pages`);
  for (const a of first.assets) byId.set(a.id, slimAsset(a));
  for (let p = 2; p <= totalPages; p++) {
    const d = await fetchJSON(`${API}?page=${p}&per_page=100&sort=asc`);
    for (const a of d.assets) byId.set(a.id, slimAsset(a));
    if (p % 10 === 0) { console.log(`  page ${p}/${totalPages} — ${byId.size} unique so far`); await sleep(150); }
  }
  const assets = [...byId.values()];
  fs.writeFileSync(MANIFEST, JSON.stringify({ harvested_at: new Date().toISOString(), count: assets.length, assets }, null, 2));
  const imgN = assets.filter((a) => a.type !== 'video').length;
  const vidN = assets.filter((a) => a.type === 'video').length;
  console.log(`manifest saved: ${assets.length} assets (${imgN} image, ${vidN} video)`);
  if (process.argv.includes('--meta-only')) { console.log('RESULT:' + JSON.stringify({ assets: assets.length, images: imgN, videos: vidN, media: 'skipped' })); return; }

  // 2. download media + previews (resumable, concurrency-limited)
  console.log(`downloading media with ${CONCURRENCY} workers…`);
  const res = await pool(assets, async (a) => {
    const out = [];
    if (a.storage_path) {
      const ext = path.extname(a.storage_path) || (a.type === 'video' ? '.mp4' : '.webp');
      out.push(await downloadTo(`${BUCKET}/${a.storage_path}`, path.join(MEDIA, a.id + ext)));
    }
    if (a.preview_storage_path) {
      const pext = path.extname(a.preview_storage_path) || '.webp';
      out.push(await downloadTo(`${BUCKET}/${a.preview_storage_path}`, path.join(PREV, a.id + pext)));
    }
    return out;
  }, CONCURRENCY);

  const onDisk = fs.readdirSync(MEDIA).length;
  console.log(`media done: ${JSON.stringify(res)} — ${onDisk} files in media/`);
  console.log('RESULT:' + JSON.stringify({ assets: assets.length, images: imgN, videos: vidN, media_files: onDisk, ...res }));
}

main().catch((e) => { console.error('HARVEST ERROR: ' + (e.stack || e)); process.exitCode = 1; });
